#include <multiset>
#include <iostream>
#include <functional>

int main() {
    using IntSet = std::multiset<int, std::greater<int>>;
    IntSet coll1;
    coll1.insert(5);

    // Insertion always succeeds and returns iterator to the new element
    IntSet::iterator ipos = coll1.insert(5); 

    std::cout << "Inserted value: " << *ipos << "\n";

    // A set would require checking ipos.second
    // std::set<int> s; auto res = s.insert(5);
}
